package com.arena.core.training;
import com.arena.core.entity.*;
import com.arena.core.repository.*;
import com.arena.core.service.*;
import com.arena.core.exception.*;
import org.junit.jupiter.api.*;
import org.springframework.security.oauth2.jwt.Jwt;
import java.util.*;
import java.time.*;
import static com.arena.core.training.TrainingRequests.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class SportLifecycleTest {
 final AcademyAuthorization authorization=mock(AcademyAuthorization.class);final CustomerRepository customers=mock(CustomerRepository.class);final AcademySportRepository sports=mock(AcademySportRepository.class);final SportCatalogueRepository catalogue=mock(SportCatalogueRepository.class);final TrainingBatchRepository batches=mock(TrainingBatchRepository.class);final BatchScheduleRepository schedules=mock(BatchScheduleRepository.class);final AuditService audit=mock(AuditService.class);final AcademySetupService setup=mock(AcademySetupService.class);
 final TrainingService service=new TrainingService(mock(AppUserRepository.class),customers,mock(CustomerAccessService.class),new AdminAuthorizationService(),catalogue,sports,mock(AcademyStaffRepository.class),batches,schedules,audit,authorization,setup,mock(AcademyPlayAreaRepository.class));
 final Jwt jwt=Jwt.withTokenValue("unit").header("alg","none").subject("owner").build();CustomerEntity academy;AcademySport badminton;SportCatalogue item;
 @BeforeEach void prepare(){academy=CustomerEntity.builder().id(10L).organizationType("ACADEMY").sports("ACADEMY").build();when(customers.findBillingCustomerForUpdate(10L)).thenReturn(Optional.of(academy));when(customers.findById(10L)).thenReturn(Optional.of(academy));var actor=new AcademyAuthorization.Actor(AppUserEntity.builder().id(1L).customerId(10L).build(),null,Set.of("OWNER"));when(authorization.manage(jwt)).thenReturn(actor);when(authorization.actor(jwt)).thenReturn(actor);badminton=new AcademySport();badminton.setId(2L);badminton.setAcademyId(10L);badminton.setVersion(0L);badminton.setName("Badminton");badminton.setRegistrationKey("BADMINTON");badminton.setCatalogueCode("BADMINTON");badminton.setActive(true);badminton.setTraining(true);badminton.setSessions(true);when(sports.findById(2L)).thenReturn(Optional.of(badminton));when(sports.saveAndFlush(any())).thenAnswer(i->i.getArgument(0));item=new SportCatalogue();item.setCode("BADMINTON");item.setLabel("Badminton");item.setActive(true);when(catalogue.findByCodeAndActiveTrue("BADMINTON")).thenReturn(Optional.of(item));when(catalogue.findAll()).thenReturn(List.of(item));}
 @Test void combinedBulkRegistersActiveUnconfiguredWithoutCreatingOperationalRecords(){var saved=service.registerActivities(jwt,new Activities(List.of(new Activity("BADMINTON",null),new Activity("OTHER","  Acro   Fitness "))));assertEquals(2,saved.size());assertTrue(saved.stream().allMatch(s->s.isActive()&&!s.isTraining()&&!s.isSessions()));assertEquals("Acro Fitness",saved.get(1).getName());verify(sports,times(2)).saveAndFlush(any());verify(setup).evaluate(academy);verify(audit).record(eq("TRAINING_ACTIVITIES_REGISTERED"),eq(10L),any(),any(),isNull(),isNull(),isNull(),eq("count=2"));verifyNoInteractions(batches,schedules);}
 @Test void completeInvalidSelectionIsReportedBeforeAnyWrite(){var exception=assertThrows(ActivitySelectionException.class,()->service.registerActivities(jwt,new Activities(List.of(new Activity("BADMINTON",null),new Activity("OTHER","badminton"),new Activity("OTHER","x")))));assertEquals(2,exception.fields().size());verify(sports,never()).saveAndFlush(any());verifyNoInteractions(audit,setup);}
 @Test void normalizedDuplicatesAndInactiveExistingRegistrationAreRejected(){when(sports.findByAcademyIdOrderByName(10L)).thenReturn(List.of(badminton));badminton.setActive(false);assertThrows(ActivitySelectionException.class,()->service.registerActivities(jwt,new Activities(List.of(new Activity("BADMINTON",null)))));when(sports.findByAcademyIdOrderByName(10L)).thenReturn(List.of());assertThrows(ActivitySelectionException.class,()->service.registerActivities(jwt,new Activities(List.of(new Activity("OTHER","Acro   Fitness"),new Activity("OTHER"," acro fitness ")))));verify(sports,never()).saveAndFlush(any());}
 @Test void neitherCapabilityIsPermittedAndStatusRemainsSeparate(){service.updateSport(jwt,2L,new SportUpdate(0L,false,false,true));assertTrue(badminton.isActive());assertFalse(badminton.isTraining());assertFalse(badminton.isSessions());}
 @Test void activeRecurringBatchBlocksDeactivationAndTrainingDisable(){var batch=new TrainingBatch();batch.setId(4L);batch.setSportId(2L);batch.setStatus("ACTIVE");batch.setStartDate(LocalDate.now().plusDays(7));when(batches.findByAcademyIdOrderByName(10L)).thenReturn(List.of(batch));assertThrows(ArenaOpsException.class,()->service.updateSport(jwt,2L,new SportUpdate(0L,true,true,false)));assertThrows(ArenaOpsException.class,()->service.updateSport(jwt,2L,new SportUpdate(0L,false,true,true)));verify(sports,never()).saveAndFlush(any());}
 @Test void expiredRecurringBatchAndUnusedConfigurationDoNotBlock(){var batch=new TrainingBatch();batch.setId(4L);batch.setSportId(2L);batch.setStatus("ACTIVE");batch.setEndDate(LocalDate.now().minusDays(1));when(batches.findByAcademyIdOrderByName(10L)).thenReturn(List.of(batch));service.updateSport(jwt,2L,new SportUpdate(0L,true,true,false));assertFalse(badminton.isActive());assertTrue(badminton.isTraining());assertTrue(badminton.isSessions());service.updateSport(jwt,2L,new SportUpdate(0L,true,true,true));assertTrue(badminton.isActive());}
 @Test void endedScheduleDoesNotBlockOpenEndedHistoricalBatch(){var batch=new TrainingBatch();batch.setId(4L);batch.setSportId(2L);batch.setStatus("ACTIVE");batch.setStartDate(LocalDate.now().minusMonths(1));var schedule=new BatchSchedule();schedule.setDayOfWeek(1);schedule.setStartTime(LocalTime.NOON);schedule.setEndTime(LocalTime.of(13,0));schedule.setEffectiveTo(LocalDate.now().minusDays(1));when(batches.findByAcademyIdOrderByName(10L)).thenReturn(List.of(batch));when(schedules.findByBatchIdAndActiveTrueOrderByDayOfWeekAscStartTimeAsc(4L)).thenReturn(List.of(schedule));service.updateSport(jwt,2L,new SportUpdate(0L,false,false,false));assertFalse(badminton.isActive());}
 @Test void customRenamePreservesIdentityCapabilitiesAndLinkedRecords(){badminton.setCatalogueCode(null);badminton.setRegistrationKey("CUSTOM:old");var renamed=service.renameSport(jwt,2L,new Rename(0L," New   Name "));assertEquals(2L,renamed.getId());assertEquals("New Name",renamed.getName());assertTrue(renamed.isTraining());verifyNoInteractions(batches,schedules);verify(audit).record(eq("TRAINING_ACTIVITY_RENAMED"),eq(10L),any(),any(),isNull(),isNull(),isNull(),eq("recordId=2"));}
 @Test void predefinedRenameAndCrossTenantUpdateAreDenied(){assertThrows(ArenaOpsException.class,()->service.renameSport(jwt,2L,new Rename(0L,"New Name")));badminton.setAcademyId(99L);assertEquals(ErrorCode.RESOURCE_NOT_FOUND,assertThrows(ArenaOpsException.class,()->service.updateSport(jwt,2L,new SportUpdate(0L,false,false,true))).getErrorCode());verify(sports,never()).saveAndFlush(any());}
 @Test void standardManagersCanManageSportsButCoachCannotAdd(){var membership=new AcademyStaff();when(authorization.manage(jwt)).thenReturn(new AcademyAuthorization.Actor(AppUserEntity.builder().customerId(10L).build(),membership,Set.of("MANAGER")));assertEquals(1,service.registerActivities(jwt,new Activities(List.of(new Activity("BADMINTON",null)))).size());when(authorization.manage(jwt)).thenThrow(new ArenaOpsException(ErrorCode.ACCESS_DENIED));assertThrows(ArenaOpsException.class,()->service.registerActivities(jwt,new Activities(List.of(new Activity("OTHER","Other Activity")))));}
 @Test void instructorsCanReadOnlyAssignedSports(){var member=new AcademyStaff();member.setSportIds(Set.of(2L));when(authorization.actor(jwt)).thenReturn(new AcademyAuthorization.Actor(AppUserEntity.builder().customerId(10L).build(),member,Set.of("INSTRUCTOR")));assertEquals(2L,service.getSport(jwt,2L).getId());member.setSportIds(Set.of());assertEquals(ErrorCode.ACCESS_DENIED,assertThrows(ArenaOpsException.class,()->service.getSport(jwt,2L)).getErrorCode());}
 @Test void clubsCanRegisterActivitiesWithoutRunningAcademySetupEvaluation(){academy.setOrganizationType("CLUB");academy.setSports("SNOOKER");assertEquals(1,service.registerActivities(jwt,new Activities(List.of(new Activity("BADMINTON",null)))).size());verifyNoInteractions(setup);}
 @Test void staleConfigurationVersionCannotWrite(){assertEquals(ErrorCode.CONFLICT,assertThrows(ArenaOpsException.class,()->service.updateSport(jwt,2L,new SportUpdate(99L,false,false,true))).getErrorCode());verify(sports,never()).saveAndFlush(any());}
}
